import webapp2

class Redirect(webapp2.RequestHandler):
    def get(self):
        to = self.request.path_qs[3:]
        if not to.startswith(("http://", "https://")):
            self.error("Expected fully qualified URL")
            return
        self.redirect(to, permanent=True)

app = webapp2.WSGIApplication([(r"/r/.*", Redirect)])

