const unsafe = new Set(["__proto__", "constructor", "prototype"]);

function set(obj, dotPath, value) {
  const parts = dotPath.split(".");
  let o = obj;
  for (let i = 0; i < parts.length - 1; i++) {
    if (unsafe.has(parts[i])) return;
    o = o[parts[i]];
  }
  o[parts[parts.length - 1]] = value;
}

app.patch("/api/v1/article/:id", (req, res) => {
  const doc = { title: "x" };
  for (const [key, value] of Object.entries(req.body)) set(doc, key, value);
  res.json(doc);
});

const path = require("node:path");
const send = require("@fastify/send");

async function serve(req, reply) {
  const prefix = "/static";
  let pathname = decodeURI(req.raw.url.split("?")[0]);
  if (pathname.startsWith(prefix)) pathname = pathname.slice(prefix.length);
  return send(req.raw, pathname, { root: "/srv/public", dotfiles: "allow" });
}

module.exports = async function (fastify) {
  fastify.get("/static/*", serve);
};

