const express = require("express");
const path = require("node:path");
const fs = require("node:fs");
const app = express();

function validateAppId(appid) {
  return appid.length < 30 && appid.indexOf("/") === -1 ? appid : null;
}

app.get("/applicationData/:appid/:version", (req, res) => {
  const appid = validateAppId(req.params.appid);
  if (!appid) return res.sendStatus(400);
  const file = path.join("/srv/.signalk", appid, `${req.params.version}.json`);
  res.type("json").send(fs.readFileSync(file));
});

